using System;using System.IO;using System.Linq;using System.Collections.Generic;using Autodesk.AutoCAD.ApplicationServices;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.Runtime;using Elevator.AutoCAD;using Elevator.Core.Shaft;
using Elevator.Core.Geometry;
public sealed class AATests {
 static string O{get{return SectionAADrawing.Output;}}
 static List<object> results=new List<object>(); static string reportName="native-tests.json";
 static void Test(string name,Action action){try{action();results.Add(new{name,status="PASS"});}catch(System.Exception e){results.Add(new{name,status="FAIL",error=e.ToString()});}Configuration.WriteJson(Path.Combine(O,reportName),results);}
 static void Check(bool b,string s){if(!b)throw new System.Exception(s);}
 public static SectionAAProject Fixture(int n,string convention="BG",string first="G",bool unequal=false){var d=new SectionAAProject();d.Floors=FloorStackGenerator.Create(n+1,convention,first,Enumerable.Range(0,n-1).Select(i=>unequal?new[]{3000.0,3200,2800,3500}[i%4]:3000).ToArray(),null);d.DisplayFloorId=(d.Floors.FirstOrDefault(f=>f.Name=="G")??d.Floors.First()).FloorId;return d;}
 static string Fingerprint(Database db,bool aa){using(var tr=db.TransactionManager.StartTransaction()){var f=aa?SectionAADrawing.Frame(SectionAADrawing.Find(db,tr)):new ShaftFrame{Origin=Point3d.Origin,XAxis=Vector3d.XAxis,YAxis=Vector3d.YAxis,ZAxis=Vector3d.ZAxis};var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var es=((BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead)).Cast<ObjectId>().Select(id=>(Entity)tr.GetObject(id,OpenMode.ForRead)).Where(e=>{var t=SectionAADrawing.Tag(e);return aa?(t!=null&&t[0].StartsWith(SectionAADrawing.Prefix)):(t==null||!t[0].StartsWith(SectionAADrawing.Prefix));}).ToArray();return SectionAADrawing.Json(es.Select(e=>new{Tag=SectionAADrawing.Tag(e),Type=e.GetRXClass().DxfName,e.Visible,Points=MachineRoomDependencies.Points(e,f),Text=e is MText?((MText)e).Contents:e is Dimension?((Dimension)e).DimensionText:null}).OrderBy(e=>e.Tag==null?e.Type:e.Tag[0]).ToArray());}}
 [CommandMethod("AATESTPREPARE")]public void Prepare(){Directory.CreateDirectory(O);var db=Application.DocumentManager.MdiActiveDocument.Database;try{SectionAADrawing.PrepareLibrary(db,Path.Combine(O,"source-reference.dwg"));var d=Fixture(5);var a=SectionAADrawing.Rebuild(db,d,new Point3d(20000,0,0));Configuration.WriteJson(Path.Combine(O,"clean-master-audit.json"),a);SectionAADrawing.ExportMaster(db);db.SaveAs(Path.Combine(O,"CleanMaster_Coordinated.dwg"),DwgVersion.AC1032);File.WriteAllText(Path.Combine(O,"prepare-status.txt"),"PASS");}catch(System.Exception e){File.WriteAllText(Path.Combine(O,"prepare-status.txt"),e.ToString());}}
 [CommandMethod("AATESTMATRIX")]public void Matrix(){var db=Application.DocumentManager.MdiActiveDocument.Database;string protectedBefore=Fingerprint(db,false);SectionAAProject baseline=Fixture(5);string baselineFp=null;int count=0;
 Action<SectionAAProject,string> run=(d,label)=>{Test(label,()=>{var a=SectionAADrawing.Rebuild(db,d,null);Check(a.MaxBracketSpacing<=d.BracketMaximum+1e-7,"Maximum spacing exceeded");Check(a.DoorCount==d.Floors.Count(f=>f.Served),"Door count");Check(Fingerprint(db,false)==protectedBefore,"Protected native views changed");string path=Path.Combine(O,"AA_"+(++count).ToString("00")+"_"+label.Replace(' ','_')+".dwg");db.SaveAs(path,DwgVersion.AC1032);Configuration.WriteJson(path+".json",a);});};
 run(Fixture(3),"G_1_2_R");run(Fixture(5,"BG","B"),"B_G_1_2_3_R");run(Fixture(6,"Numeric","-2"),"Numeric_6");run(baseline,"Five_stops");baselineFp=Fingerprint(db,true);run(Fixture(8),"Eight_stops");run(Fixture(12),"Twelve_stops");run(baseline,"Return_five");Test("Small_large_small_no_drift",()=>Check(baselineFp==Fingerprint(db,true),"Drift"));
 var unequal=Fixture(5,"BG","G",true);run(unequal,"Unequal_heights");unequal.Floors[2].Served=false;run(unequal,"NoStop_intermediate");unequal.Floors[3].Served=false;run(unequal,"Multiple_NoStop");
 run(baseline,"Reversible_baseline");baselineFp=Fingerprint(db,true);baseline.Pit=1500;run(baseline,"Pit_1500");baseline.Pit=1000;run(baseline,"Pit_1000");Test("Pit_roundtrip",()=>Check(baselineFp==Fingerprint(db,true),"Pit drift"));baseline.OH=4500;run(baseline,"OH_4500");baseline.OH=4200;run(baseline,"OH_4200");Test("OH_roundtrip",()=>Check(baselineFp==Fingerprint(db,true),"OH drift"));
 foreach(double spacing in new[]{3000.0,2000,1500,1000}){baseline.BracketMaximum=spacing;run(baseline,"Spacing_"+spacing);}baseline.BracketMaximum=1500;
 string carId=baseline.DisplayFloorId;baseline.DisplayFloorId=baseline.Floors[2].FloorId;run(baseline,"Car_at_2");baseline.DisplayFloorId=carId;run(baseline,"Car_return_G");Test("Car_roundtrip",()=>Check(baselineFp==Fingerprint(db,true),"Car drift"));
 var inserted=new VerticalFloor{FloorId="test_insert",Name="NEW",Served=true,FflZ=9000};baseline.Floors.Insert(3,inserted);for(int i=4;i<baseline.Floors.Count-1;i++)baseline.Floors[i].FflZ+=3000;run(baseline,"Insert_floor");baseline.Floors.RemoveAt(3);for(int i=3;i<baseline.Floors.Count-1;i++)baseline.Floors[i].FflZ-=3000;run(baseline,"Remove_inserted_floor");Test("Insert_remove_roundtrip",()=>Check(baselineFp==Fingerprint(db,true),"Insertion drift"));
 Test("Invalid_interval_atomic",()=>{var bad=Fixture(3);bad.Floors[1].FflZ=2000;string before=Fingerprint(db,true);bool rejected=false;try{SectionAADrawing.Rebuild(db,bad,null);}catch(ArgumentException){rejected=true;}Check(rejected&&before==Fingerprint(db,true),"Invalid geometry changed drawing");});
 Test("Rename_preserves_ID",()=>{var id=baseline.Floors[1].FloorId;baseline.Floors[1].Name="LOBBY";SectionAADrawing.Rebuild(db,baseline,null);using(var tr=db.TransactionManager.StartTransaction())Check(SectionAADrawing.Find(db,tr).Keys.Any(k=>k.Contains(id)),"Floor identity lost");baseline.Floors[1].Name="1";});
 SectionAADrawing.Rebuild(db,baseline,null);db.SaveAs(Path.Combine(O,"SectionAA_Review.dwg"),DwgVersion.AC1032);File.WriteAllText(Path.Combine(O,"reopen-fingerprint.txt"),Fingerprint(db,true));
 }
 [CommandMethod("AATESTREOPEN")]public void Reopen(){reportName="fresh-reopen-tests.json";var db=Application.DocumentManager.MdiActiveDocument.Database;Test("Fresh_process_save_reopen",()=>{using(var tr=db.TransactionManager.StartTransaction())SectionAADrawing.Audit(db,tr);Check(Fingerprint(db,true)==File.ReadAllText(Path.Combine(O,"reopen-fingerprint.txt")),"Reopened fingerprint differs");});Configuration.WriteJson(Path.Combine(O,"fresh-reopen-tests.json"),results);}
 [CommandMethod("AATESTINSTALL")]public void InstallChecks(){reportName="installation-tests.json";var db=Application.DocumentManager.MdiActiveDocument.Database;string protectedBefore=Fingerprint(db,false);var d=Fixture(5);
 Test("Clean_master_install_at_arbitrary_datum",()=>{SectionAADrawing.ImportLibrary(db);SectionAADrawing.Rebuild(db,d,new Point3d(32000,-5000,0));Check(Fingerprint(db,false)==protectedBefore,"Protected views changed");});
 Test("Duplicate_install_command_rejected_without_changes",()=>{string before=Fingerprint(db,true);new SectionAACommands().Install();Check(before==Fingerprint(db,true),"Duplicate install changed A-A");});
 Test("Rotated_and_translated_semantic_frame_update",()=>{using(var tr=db.TransactionManager.StartTransaction()){var all=SectionAADrawing.Find(db,tr);var f=SectionAADrawing.Frame(all);var transform=Matrix3d.Displacement(new Vector3d(1234,5678,0))*Matrix3d.Rotation(.25,Vector3d.ZAxis,f.Origin);foreach(var e in all.Values){e.UpgradeOpen();e.TransformBy(transform);}tr.Commit();}SectionAADrawing.Rebuild(db,d,null);using(var tr=db.TransactionManager.StartTransaction()){var f=SectionAADrawing.Frame(SectionAADrawing.Find(db,tr));Check(Math.Abs(f.XAxis.X-Math.Cos(.25))<1e-8,"Rotation lost");Check(f.Origin.DistanceTo(new Point3d(33234,678,0))<1e-6,"Translation lost");}});
 Func<string,double> minZ=prefix=>{using(var tr=db.TransactionManager.StartTransaction()){var all=SectionAADrawing.Find(db,tr);var frame=SectionAADrawing.Frame(all);return all.Where(p=>p.Key.StartsWith(SectionAADrawing.Prefix+prefix)).SelectMany(p=>MachineRoomDependencies.Points(p.Value,frame)).Min(p=>p.Y);}};
 Test("Measured_car_CW_opposite_1_to_1_motion",()=>{double car=minZ("Car."),cw=minZ("CW.");d.DisplayFloorId=d.Floors[2].FloorId;SectionAADrawing.Rebuild(db,d,null);Check(Math.Abs(minZ("Car.")-car-6000)<.03,"Car movement");Check(Math.Abs(minZ("CW.")-cw+6000)<.03,"CW movement");Check(Fingerprint(db,false)==protectedBefore,"Protected views changed");});
 db.SaveAs(Path.Combine(O,"SectionAA_Installation_Rotation.dwg"),DwgVersion.AC1032);
 }}


